<?php
/**
 * lib.php — storage, accounts, sessions, logging and the Gemini client.
 *
 * Built for cPanel shared hosting: flat JSON files under a directory outside
 * the webroot, no database, no extensions beyond curl. Writes go through a
 * temp-file-and-rename so a crash mid-write cannot leave a half-written record.
 */

declare(strict_types=1);

// ================================================================ config ===

/** Dynamic data directory configuration: respects environment or falls back safely */
if (!defined('DATA_DIR')) {
    $envDir = getenv('GEMINI_DATA_DIR');
    if ($envDir && is_string($envDir)) {
        define('DATA_DIR', rtrim($envDir, '/\\'));
    } elseif (is_dir('/home/z0x1dxbvef29/gemini-data') && is_writable('/home/z0x1dxbvef29/gemini-data')) {
        define('DATA_DIR', '/home/z0x1dxbvef29/gemini-data');
    } else {
        define('DATA_DIR', dirname(__DIR__) . '/gemini-data');
    }
}

/** Your own password for the admin pages. Can be set via GEMINI_ADMIN_PASSWORD env var. */
$adminPw = getenv('GEMINI_ADMIN_PASSWORD');
define('ADMIN_PASSWORD', ($adminPw && is_string($adminPw)) ? $adminPw : 'CHANGE-ME-ADMIN');

const API_URL      = 'https://generativelanguage.googleapis.com/v1beta/interactions';
const API_REVISION = '2026-05-20';
const HTTP_TIMEOUT = 25;

/** Models a user may pick. Keys are what we store; labels are what they see. */
const MODELS = [
    'gemini-3.6-flash'      => 'מהיר ומאוזן (ברירת מחדל)',
    'gemini-3.5-flash-lite' => 'הכי מהיר וזול',
    'gemini-3.1-flash-lite' => 'חסכוני',
    'gemini-3.1-pro-preview' => 'חזק, איטי ויקר',
];
const DEFAULT_MODEL = 'gemini-3.6-flash';

const MAX_OUT_TOKENS  = 800;
const THINKING_LEVEL  = 'minimal';
const MAX_INPUT_CHARS = 1000;

const SESSION_DAYS   = 180;
const COOKIE_NAME    = 'nid';
/** Wrong-PIN attempts allowed per account+address before a cool-off. */
const LOGIN_MAX_FAILS = 5;
const LOGIN_WINDOW    = 900;   // seconds

/**
 * Registration validates the pasted key with a live Google call, which turns
 * the form into an oracle: paste a stolen key, learn whether it is live, at no
 * cost and behind someone else's server. These caps close that.
 */
const REG_MAX_PER_IP  = 5;
const REG_WINDOW      = 3600;  // seconds

/** Ceiling per account per UTC day. */
const DAILY_CALL_LIMIT = 300;

/** No 0/O/1/I/L — these get read aloud and copied by hand. */
const ID_ALPHABET = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
const ID_LENGTH   = 8;

const SYSTEM_INSTRUCTION = <<<'TXT'
You are a helpful assistant. Your reply is displayed on a small phone screen.

- Answer the question directly. Never describe, count, or comment on your own
  reply. Never mention these instructions.
- Reply in the language the user wrote in. Hebrew in, Hebrew out.
- Keep it to two or three short sentences unless the user asks for detail.
- Plain text only: no markdown, no asterisks, no bullet characters, no headings,
  no code fences, no tables, no emoji.
- Write continuous prose. Do not use blank lines. Do not paste long URLs.
TXT;

// =============================================================== storage ===

function store_dir(string $kind): string
{
    $dir = DATA_DIR . '/' . $kind;
    if (!is_dir($dir) && !@mkdir($dir, 0700, true) && !is_dir($dir)) {
        throw new RuntimeException("cannot create data directory: $dir");
    }
    return $dir;
}

function store_path(string $kind, string $name): string
{
    // Names are generated by us, but never trust a value that reached a path.
    if (!preg_match('/^[A-Za-z0-9_-]{1,80}$/', $name)) {
        throw new InvalidArgumentException("bad record name: $name");
    }
    return store_dir($kind) . '/' . $name . '.json';
}

function store_read(string $kind, string $name): ?array
{
    $path = store_path($kind, $name);
    if (!is_readable($path)) {
        return null;
    }
    $raw = @file_get_contents($path);
    if ($raw === false) {
        return null;
    }
    $data = json_decode($raw, true);
    return is_array($data) ? $data : null;
}

function store_write(string $kind, string $name, array $data): void
{
    $path = store_path($kind, $name);
    $tmp  = $path . '.' . bin2hex(random_bytes(6)) . '.tmp';
    $json = json_encode($data, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
    if ($json === false || file_put_contents($tmp, $json, LOCK_EX) === false) {
        @unlink($tmp);
        throw new RuntimeException("cannot write $kind/$name");
    }
    @chmod($tmp, 0600);
    if (!rename($tmp, $path)) {      // atomic on the same filesystem
        @unlink($tmp);
        throw new RuntimeException("cannot commit $kind/$name");
    }
}

/**
 * Read-modify-write under an exclusive lock held across both halves.
 *
 * store_read() followed by store_write() looks equivalent but is not: two
 * overlapping requests both read the old value and the second write wins, so
 * counters silently undercount. That matters most for the login-failure
 * counter, where undercounting weakens the throttle.
 *
 * @param callable(array):array $fn
 */
function store_update(string $kind, string $name, callable $fn): array
{
    $path = store_path($kind, $name);
    $fh   = fopen($path, 'c+');
    if ($fh === false) {
        throw new RuntimeException("cannot open $kind/$name for update");
    }
    try {
        if (!flock($fh, LOCK_EX)) {
            throw new RuntimeException("cannot lock $kind/$name");
        }
        $raw  = stream_get_contents($fh);
        $data = json_decode((string) $raw, true);
        $data = $fn(is_array($data) ? $data : []);

        $json = json_encode($data, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
        if ($json === false) {
            throw new RuntimeException("cannot encode $kind/$name");
        }
        rewind($fh);
        ftruncate($fh, 0);
        fwrite($fh, $json);
        fflush($fh);
        @chmod($path, 0600);
        return $data;
    } finally {
        @flock($fh, LOCK_UN);
        fclose($fh);
    }
}

function store_delete(string $kind, string $name): void
{
    @unlink(store_path($kind, $name));
}

function store_list(string $kind): array
{
    $out = [];
    foreach (glob(store_dir($kind) . '/*.json') ?: [] as $f) {
        $out[] = basename($f, '.json');
    }
    return $out;
}

// =============================================================== logging ===

/**
 * One JSON object per line, one file per day. Never records the API key, the
 * PIN, or the full session token — only enough to tell you where a flow broke.
 */
function log_event(string $stage, string $result, array $extra = []): void
{
    try {
        $line = json_encode([
            'ts'     => gmdate('c'),
            'stage'  => $stage,
            'result' => $result,
            'ip'     => substr((string) ($_SERVER['REMOTE_ADDR'] ?? '-'), 0, 45),
        ] + $extra, JSON_UNESCAPED_UNICODE);
        @file_put_contents(store_dir('logs') . '/' . gmdate('Y-m-d') . '.jsonl',
                           $line . "\n", FILE_APPEND | LOCK_EX);
    } catch (Throwable) {
        // logging must never break the request
    }
}

function log_read(string $day, ?string $account = null, int $limit = 200): array
{
    $path = store_dir('logs') . '/' . preg_replace('/[^0-9-]/', '', $day) . '.jsonl';
    if (!is_readable($path)) {
        return [];
    }
    $rows = [];
    foreach (array_reverse(file($path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: []) as $line) {
        $row = json_decode($line, true);
        if (!is_array($row)) {
            continue;
        }
        if ($account !== null && ($row['account'] ?? null) !== $account) {
            continue;
        }
        $rows[] = $row;
        if (count($rows) >= $limit) {
            break;
        }
    }
    return $rows;
}

function log_days(): array
{
    $days = [];
    foreach (glob(store_dir('logs') . '/*.jsonl') ?: [] as $f) {
        $days[] = basename($f, '.jsonl');
    }
    rsort($days);
    return $days;
}

// ============================================================== accounts ===

function new_account_id(): string
{
    $alpha = ID_ALPHABET;
    $max   = strlen($alpha) - 1;
    for ($try = 0; $try < 20; $try++) {
        $id = '';
        for ($i = 0; $i < ID_LENGTH; $i++) {
            $id .= $alpha[random_int(0, $max)];
        }
        if (store_read('accounts', $id) === null) {
            return $id;
        }
    }
    throw new RuntimeException('could not allocate an account id');
}

/**
 * Shown once at registration, never again. Only its hash is kept, and the hash
 * is always taken over the normalised form so the dashes are pure decoration
 * and the user may type it in any case, with or without them.
 */
function new_recovery_code(): string
{
    $alpha = ID_ALPHABET;
    $max   = strlen($alpha) - 1;
    $out   = '';
    for ($i = 0; $i < 16; $i++) {
        if ($i > 0 && $i % 4 === 0) {
            $out .= '-';
        }
        $out .= $alpha[random_int(0, $max)];
    }
    return $out;
}

function normalise_code(string $code): string
{
    return strtoupper((string) preg_replace('/[^A-Za-z0-9]/', '', $code));
}

/** @return array{0:array,1:string} the account, and the plaintext recovery code */
function account_create(string $apiKey, string $pin, string $label, string $email = ''): array
{
    $id       = new_account_id();
    $recovery = new_recovery_code();
    $acc = [
        'id'            => $id,
        'api_key'       => $apiKey,
        'pin_hash'      => password_hash($pin, PASSWORD_DEFAULT),
        'recovery_hash' => password_hash(normalise_code($recovery), PASSWORD_DEFAULT),
        'email'         => $email,
        'label'         => $label,
        'model'         => DEFAULT_MODEL,
        'created'       => gmdate('c'),
        'last_seen'     => gmdate('c'),
        'calls'         => 0,
        'errors'        => 0,
        'day'           => gmdate('Y-m-d'),
        'day_calls'     => 0,
    ];
    store_write('accounts', $id, $acc);
    log_event('register', 'ok', ['account' => $id, 'label' => $label, 'email' => $email !== '']);
    return [$acc, $recovery];
}

/**
 * Burn the recovery code to set a new PIN. Single use: a fresh code is issued
 * so the account is never left without a way back in.
 * @return array{0:bool,1:string} success, and the new recovery code
 */
function account_recover(string $id, string $code, string $newPin): array
{
    $acc = account_load($id);
    if ($acc === null || ($acc['recovery_hash'] ?? '') === '') {
        return [false, ''];
    }
    if (!password_verify(normalise_code($code), (string) $acc['recovery_hash'])) {
        return [false, ''];
    }
    $fresh = new_recovery_code();
    store_update('accounts', (string) $acc['id'], function (array $a) use ($newPin, $fresh) {
        $a['pin_hash']      = password_hash($newPin, PASSWORD_DEFAULT);
        $a['recovery_hash'] = password_hash(normalise_code($fresh), PASSWORD_DEFAULT);
        return $a;
    });
    session_end_all((string) $acc['id']);
    log_event('recover', 'ok', ['account' => $acc['id']]);
    return [true, $fresh];
}

function account_load(string $id): ?array
{
    $id = strtoupper(trim($id));
    if (!preg_match('/^[A-Z0-9]{1,16}$/', $id)) {
        return null;
    }
    return store_read('accounts', $id);
}

function account_save(array $acc): void
{
    store_write('accounts', $acc['id'], $acc);
}

/** Counter bump under a lock, so two concurrent asks cannot lose one another. */
function account_touch(array &$acc, bool $wasError = false): void
{
    $today = gmdate('Y-m-d');
    $acc = store_update('accounts', (string) $acc['id'], function (array $a) use ($wasError, $today) {
        $a['last_seen'] = gmdate('c');
        $a['calls']     = (int) ($a['calls'] ?? 0) + 1;
        if ($wasError) {
            $a['errors'] = (int) ($a['errors'] ?? 0) + 1;
        }
        if (($a['day'] ?? '') !== $today) {
            $a['day']        = $today;
            $a['day_calls']  = 0;
        }
        $a['day_calls'] = (int) ($a['day_calls'] ?? 0) + 1;
        return $a;
    });
}

/**
 * Daily ceiling per account. Even though each user pays for their own key, a
 * leaked account id on a plaintext link would otherwise let a stranger drain
 * that quota unnoticed.
 */
function quota_left(array $acc): int
{
    $today = gmdate('Y-m-d');
    $used  = ($acc['day'] ?? '') === $today ? (int) ($acc['day_calls'] ?? 0) : 0;
    return max(0, DAILY_CALL_LIMIT - $used);
}

// ========================================================== rate limiting ===

/**
 * Throttling is keyed on account *and* client address. Keying on the account
 * alone would let anyone who knows an id lock its owner out by guessing wrong
 * five times — a denial of service dressed up as a security control.
 */
function login_key(string $id): string
{
    $ip = (string) ($_SERVER['REMOTE_ADDR'] ?? '0.0.0.0');
    return substr(hash('sha256', strtoupper($id) . '|' . $ip), 0, 32);
}

function login_blocked(string $id): bool
{
    $key = login_key($id);
    $rec = store_read('ratelimit', $key);
    if ($rec === null) {
        return false;
    }
    if (time() - (int) ($rec['first'] ?? 0) > LOGIN_WINDOW) {
        store_delete('ratelimit', $key);
        return false;
    }
    return (int) ($rec['fails'] ?? 0) >= LOGIN_MAX_FAILS;
}

function login_fail(string $id): void
{
    store_update('ratelimit', login_key($id), function (array $rec) {
        if (!$rec || time() - (int) ($rec['first'] ?? 0) > LOGIN_WINDOW) {
            $rec = ['first' => time(), 'fails' => 0];
        }
        $rec['fails'] = (int) $rec['fails'] + 1;
        return $rec;
    });
}

function login_ok(string $id): void
{
    store_delete('ratelimit', login_key($id));
}

// -------------------------------------------------- registration throttle ---

function reg_key(): string
{
    $ip = (string) ($_SERVER['REMOTE_ADDR'] ?? '0.0.0.0');
    return 'reg' . substr(hash('sha256', $ip), 0, 29);
}

function reg_blocked(): bool
{
    $rec = store_read('ratelimit', reg_key());
    if ($rec === null) {
        return false;
    }
    if (time() - (int) ($rec['first'] ?? 0) > REG_WINDOW) {
        store_delete('ratelimit', reg_key());
        return false;
    }
    return (int) ($rec['tries'] ?? 0) >= REG_MAX_PER_IP;
}

function reg_attempt(): void
{
    store_update('ratelimit', reg_key(), function (array $rec) {
        if (!$rec || time() - (int) ($rec['first'] ?? 0) > REG_WINDOW) {
            $rec = ['first' => time(), 'tries' => 0];
        }
        $rec['tries'] = (int) $rec['tries'] + 1;
        return $rec;
    });
}

// ============================================================== sessions ===

/**
 * The cookie holds the raw token; only its hash is stored. A leaked data
 * directory therefore does not hand over working sessions.
 */
function session_start_for(string $accountId, string $deviceName = ''): string
{
    $token = bin2hex(random_bytes(24));
    store_write('sessions', hash('sha256', $token), [
        'account'   => $accountId,
        'created'   => gmdate('c'),
        'last_seen' => gmdate('c'),
        'device'    => substr($deviceName, 0, 60),
        'ua'        => substr((string) ($_SERVER['HTTP_USER_AGENT'] ?? '-'), 0, 120),
    ]);
    setcookie(COOKIE_NAME, $token, [
        'expires'  => time() + SESSION_DAYS * 86400,
        'path'     => '/',
        'httponly' => true,
        'samesite' => 'Lax',
    ]);
    log_event('session', 'created', ['account' => $accountId]);
    return $token;
}

function session_current(): ?array
{
    $token = (string) ($_COOKIE[COOKIE_NAME] ?? '');
    if ($token === '' || !preg_match('/^[a-f0-9]{48}$/', $token)) {
        return null;
    }
    $key = hash('sha256', $token);
    $sess = store_read('sessions', $key);
    if ($sess === null) {
        return null;
    }
    $acc = account_load((string) $sess['account']);
    if ($acc === null) {
        store_delete('sessions', $key);
        return null;
    }
    $sess['_key']    = $key;
    $sess['_account'] = $acc;
    return $sess;
}

function session_end(string $key): void
{
    store_delete('sessions', $key);
    setcookie(COOKIE_NAME, '', ['expires' => time() - 3600, 'path' => '/']);
}

function session_end_all(string $accountId): int
{
    $n = 0;
    foreach (store_list('sessions') as $key) {
        $s = store_read('sessions', $key);
        if ($s !== null && ($s['account'] ?? '') === $accountId) {
            store_delete('sessions', $key);
            $n++;
        }
    }
    setcookie(COOKIE_NAME, '', ['expires' => time() - 3600, 'path' => '/']);
    log_event('session', 'revoked_all', ['account' => $accountId, 'count' => $n]);
    return $n;
}

function sessions_of(string $accountId): array
{
    $out = [];
    foreach (store_list('sessions') as $key) {
        $s = store_read('sessions', $key);
        if ($s !== null && ($s['account'] ?? '') === $accountId) {
            $s['_key'] = $key;
            $out[] = $s;
        }
    }
    usort($out, fn($a, $b) => strcmp((string) $b['created'], (string) $a['created']));
    return $out;
}

// ================================================================ gemini ===

function tighten(string $s): string
{
    $s = str_replace("\r\n", "\n", $s);
    $s = preg_replace('/[ \t]+\n/', "\n", $s);
    $s = preg_replace('/\n{2,}/', "\n", $s);
    return trim((string) $s);
}

function extract_text(array $data): string
{
    if (isset($data['output_text']) && is_string($data['output_text'])) {
        return tighten($data['output_text']);
    }
    $chunks = [];
    foreach ($data['steps'] ?? [] as $step) {
        if (($step['type'] ?? '') !== 'model_output') {
            continue;      // skip `thought` steps, which precede every answer
        }
        foreach ($step['content'] ?? [] as $part) {
            if (($part['type'] ?? '') === 'text' && isset($part['text'])) {
                $chunks[] = $part['text'];
            }
        }
    }
    return tighten(implode('', $chunks));
}

/**
 * @return array{ok:bool,text:string,id:string,error:string,status:int,ms:int,usage:array}
 */
function gemini_call(string $apiKey, string $model, string $prompt,
                     string $previousId = '', bool $withSystem = true): array
{
    $body = [
        'model'             => $model,
        'input'             => $prompt,
        'generation_config' => [
            'max_output_tokens' => MAX_OUT_TOKENS,
            'thinking_level'    => THINKING_LEVEL,
        ],
    ];
    if ($withSystem) {
        $body['system_instruction'] = SYSTEM_INSTRUCTION;
    }
    if ($previousId !== '') {
        $body['previous_interaction_id'] = $previousId;
    }

    $t0 = microtime(true);
    $ch = curl_init(API_URL);
    curl_setopt_array($ch, [
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode($body, JSON_UNESCAPED_UNICODE),
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT        => HTTP_TIMEOUT,
        CURLOPT_HTTPHEADER     => [
            'Content-Type: application/json',
            'x-goog-api-key: ' . $apiKey,
            'Api-Revision: ' . API_REVISION,
        ],
    ]);
    $raw    = curl_exec($ch);
    $errMsg = curl_error($ch);
    $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    $ms = (int) round((microtime(true) - $t0) * 1000);

    $fail = fn(string $m) => ['ok' => false, 'text' => '', 'id' => '', 'error' => $m,
                              'status' => $status, 'ms' => $ms, 'usage' => []];

    if ($errMsg !== '') {
        return $fail('שגיאת רשת מול Google: ' . $errMsg);
    }
    $data = json_decode((string) $raw, true);
    if (!is_array($data)) {
        return $fail('תשובה לא תקינה מהשרת (HTTP ' . $status . ').');
    }
    if ($status < 200 || $status >= 300) {
        return $fail($data['error']['message'] ?? ('HTTP ' . $status));
    }
    $text = extract_text($data);
    if ($text === '') {
        return $fail('התקבלה תשובה ריקה.');
    }
    if (($data['status'] ?? '') === 'incomplete') {
        $text .= ' […]';
    }
    return ['ok' => true, 'text' => $text, 'id' => (string) ($data['id'] ?? ''),
            'error' => '', 'status' => $status, 'ms' => $ms,
            'usage' => (array) ($data['usage'] ?? [])];
}

/** Cheap round-trip used to prove a pasted key actually works before storing it. */
function gemini_validate_key(string $apiKey): array
{
    return gemini_call($apiKey, DEFAULT_MODEL, 'Reply with the single word: OK', '', false);
}

// ================================================================= utils ===

function e(string $s): string
{
    return htmlspecialchars($s, ENT_QUOTES | ENT_XML1, 'UTF-8');
}

/** Character-safe truncation that does not need mbstring. */
function utf8_cut(string $s, int $max): string
{
    if (function_exists('mb_substr')) {
        return mb_substr($s, 0, $max, 'UTF-8');
    }
    if (preg_match('/^.{0,' . $max . '}/us', $s, $m) === 1) {
        return $m[0];
    }
    return substr($s, 0, $max);
}

function model_label(string $model): string
{
    return MODELS[$model] ?? $model;
}
